function addCurriculumTopic(data) {
  const makeQuestions = (suffix, rows) => rows.map((row, index) => {
    if (!Array.isArray(row)) return row;
    const [question, answers, correctAnswer, explanation] = row;
    const offset = index % answers.length;
    const shuffledAnswers = answers.map((answer, answerIndex) => answers[(answerIndex + offset) % answers.length]);
    return {
      id: `${data.id}-${suffix}${index + 1}`, type: 'single', question, answers: shuffledAnswers,
      correctAnswer: (correctAnswer - offset + answers.length) % answers.length, explanation, rule: explanation
    };
  });
  const questions = makeQuestions('q', data.questions);
  COURSE_TOPICS.push({
    id: data.id, grade: data.grade, subjectId: data.subjectId, section: data.section,
    title: data.title, description: data.description, difficulty: data.difficulty || 'medium',
    theoryHtml: data.theoryHtml,
    practiceQuestions: makeQuestions('p', data.questions.slice(0, 2)),
    tests: [{ id: `${data.id}-test`, title: data.title, difficulty: 3, estimatedTime: 5, questions }]
  });
}

[
  { id: 'geography-5-maps', grade: 5, subjectId: 'geography', section: 'План и карта', title: 'Условные знаки карты', description: 'Масштаб, стороны горизонта и условные знаки.', difficulty: 'easy', theoryHtml: '<h3>Как читать карту</h3><p>Карта — уменьшенное изображение земной поверхности. Масштаб показывает, во сколько раз расстояние на местности больше расстояния на карте.</p><div class="theory-callout"><strong>Запомни:</strong> север обычно расположен вверху карты; условные знаки объясняются в легенде.</div>', questions: [['Где обычно расположен север на карте?', ['Вверху', 'Внизу', 'Справа'], 0, 'По традиции север располагают в верхней части карты.'], ['Что объясняет условный знак?', ['Объект или явление на карте', 'Температуру воздуха', 'Время года'], 0, 'Условный знак обозначает объект, а его значение раскрывает легенда.'], ['Что показывает масштаб карты?', ['Соотношение расстояний карты и местности', 'Высоту облаков', 'Число стран'], 0, 'Масштаб показывает степень уменьшения реальных расстояний.'], TOPIC_QUESTION('geography-5-maps-q4', 'single', "Каким цветом на физической карте изображают реки и озёра?", ["коричневым","зелёным","голубым"], 2, "Водные объекты на картах принято показывать голубым и синим цветом."), TOPIC_QUESTION('geography-5-maps-q5', 'single', "Где можно узнать, что обозначает условный знак?", ["в легенде (системе условных знаков) карты","в числовом масштабе","в названии карты"], 0, "Легенда карты объясняет значение всех условных знаков.")] },
  { id: 'history-5-ancient', grade: 5, subjectId: 'history', section: 'Древний мир', title: 'Первые цивилизации', description: 'Возникновение древних государств у крупных рек.', difficulty: 'easy', theoryHtml: '<h3>Цивилизации речных долин</h3><p>Древние государства возникали у крупных рек: вода помогала земледелию, а разливы оставляли плодородный ил. Для управления орошением требовалась совместная организация труда.</p><div class="theory-callout"><strong>Пример:</strong> Египетская цивилизация развивалась в долине Нила.</div>', questions: [['У какой реки развивался Древний Египет?', ['Нил', 'Волга', 'Рейн'], 0, 'Древний Египет располагался в долине реки Нил.'], ['Почему речные долины были удобны для земледелия?', ['Вода и плодородные почвы', 'Отсутствие смены времён года', 'Близость океана'], 0, 'Реки давали воду для полива, а разливы приносили плодородный ил.'], ['Как называли письменные знаки древних египтян?', ['Иероглифы', 'Кириллица', 'Руны'], 0, 'Египтяне использовали иероглифическое письмо.'], TOPIC_QUESTION('history-5-ancient-q4', 'single', "Как называли правителя Древнего Египта?", ["шах","цезарь","фараон"], 2, "Верховного правителя Египта именовали фараоном."), TOPIC_QUESTION('history-5-ancient-q5', 'single', "В какой долине возникло Вавилонское царство?", ["в Междуречье Тигра и Евфрата","в долине Нила","в долине Инда"], 0, "Вавилон располагался между реками Тигр и Евфрат.")] },
  { id: 'biology-6-plants', grade: 6, subjectId: 'biology', section: 'Растения', title: 'Фотосинтез', description: 'Роль света, воды и углекислого газа в питании растений.', difficulty: 'medium', theoryHtml: '<h3>Образование органических веществ</h3><p>На свету зелёные растения используют воду и углекислый газ, образуя органические вещества и выделяя кислород. Процесс происходит в хлоропластах с участием хлорофилла.</p><div class="formula-card">углекислый газ + вода + свет → органическое вещество + кислород</div>', questions: [['Где в клетке растения происходит фотосинтез?', ['В хлоропластах', 'В ядре', 'В клеточной стенке'], 0, 'В хлоропластах находится хлорофилл, поглощающий свет.'], ['Какой газ выделяется при фотосинтезе?', ['Кислород', 'Азот', 'Водород'], 0, 'При фотосинтезе растения выделяют кислород.'], ['Что необходимо растениям для фотосинтеза?', ['Свет, вода и углекислый газ', 'Только кислород', 'Только минеральная соль'], 0, 'Для процесса нужны световая энергия, вода и углекислый газ.'], TOPIC_QUESTION('biology-6-plants-q4', 'single', "Какое органическое вещество образуется в листьях на свету?", ["белок","крахмал","жир"], 1, "В результате фотосинтеза в листьях образуется крахмал."), TOPIC_QUESTION('biology-6-plants-q5', 'single', "Какой газ растения поглощают из воздуха при фотосинтезе?", ["кислород","азот","углекислый газ"], 2, "Из воздуха растения усваивают углекислый газ, а кислород выделяют.")] },
  { id: 'geography-6-lithosphere', grade: 6, subjectId: 'geography', section: 'Литосфера', title: 'Внутреннее строение Земли', description: 'Земная кора, мантия и ядро.', difficulty: 'medium', theoryHtml: '<h3>Оболочки Земли</h3><p>Внутреннее строение Земли включает земную кору, мантию и ядро. Самая тонкая внешняя твёрдая оболочка — земная кора.</p><div class="theory-callout"><strong>Запомни порядок снаружи внутрь:</strong> кора, мантия, ядро.</div>', questions: [['Какой слой Земли находится снаружи?', ['Земная кора', 'Мантия', 'Ядро'], 0, 'Земная кора — внешняя твёрдая оболочка планеты.'], ['Какой слой расположен между корой и ядром?', ['Мантия', 'Атмосфера', 'Гидросфера'], 0, 'Мантия находится под земной корой и окружает ядро.'], ['Как называется центральная часть Земли?', ['Ядро', 'Кора', 'Литосфера'], 0, 'В центре Земли расположено ядро.'], TOPIC_QUESTION('geography-6-lithosphere-q4', 'single', "Как называются подземные толчки и колебания земной поверхности?", ["извержения","оползни","землетрясения"], 2, "Колебания земной коры называют землетрясениями."), TOPIC_QUESTION('geography-6-lithosphere-q5', 'single', "Как называется прибор, записывающий колебания земной поверхности?", ["сейсмограф","нивелир","флюгер"], 0, "Сейсмограф с самописцем регистрирует толчки землетрясений.")] },
  { id: 'physics-7-speed', grade: 7, subjectId: 'physics', section: 'Механическое движение', title: 'Скорость и путь', description: 'Равномерное движение и расчёт скорости.', difficulty: 'easy', theoryHtml: '<h3>Скорость движения</h3><p>Скорость показывает, какой путь тело проходит за единицу времени. При равномерном движении скорость постоянна.</p><div class="formula-card">v = s / t</div><div class="theory-callout"><strong>Единицы:</strong> в СИ скорость измеряется в метрах в секунду (м/с).</div>', questions: [['Как найти скорость при известном пути и времени?', ['Разделить путь на время', 'Умножить путь на время', 'Вычесть время из пути'], 0, 'Скорость вычисляется по формуле v = s/t.'], ['Какова скорость тела, прошедшего 60 м за 10 с?', ['6 м/с', '50 м/с', '600 м/с'], 0, 'v = 60/10 = 6 м/с.'], ['В каких единицах скорость выражается в СИ?', ['м/с', 'кг', 'Н'], 0, 'Основная единица скорости в СИ — метр в секунду.'], TOPIC_QUESTION('physics-7-speed-q4', 'input', "Тело движется со скоростью 5 м/с в течение 10 с. Какой путь оно пройдёт (в метрах)?", null, "50", "Путь равен произведению скорости на время: 5 · 10 = 50 м."), TOPIC_QUESTION('physics-7-speed-q5', 'single', "Сколько километров в час составляет скорость 1 м/с?", ["1 км/ч","3,6 км/ч","10 км/ч"], 1, "1 м/с = 0,001 км / (1/3600 ч) = 3,6 км/ч.")] },
  { id: 'algebra-9-quadratics', grade: 9, subjectId: 'algebra', section: 'Квадратная функция', title: 'График параболы', description: 'Вершина и направление ветвей квадратичной функции.', difficulty: 'medium', theoryHtml: '<h3>Квадратичная функция</h3><p>График функции y = ax² + bx + c — парабола. При a &gt; 0 её ветви направлены вверх, при a &lt; 0 — вниз.</p><div class="theory-callout"><strong>Вершина:</strong> абсцисса вершины равна x = −b/(2a).</div>', questions: [['Куда направлены ветви y = 2x²?', ['Вверх', 'Вниз', 'Парабола не имеет ветвей'], 0, 'Коэффициент a положителен, поэтому ветви направлены вверх.'], ['Какой график имеет функция y = ax² + bx + c?', ['Парабола', 'Гипербола', 'Окружность'], 0, 'График квадратичной функции является параболой.'], ['Найди абсциссу вершины y = x² − 4x + 1.', ['2', '−2', '4'], 0, 'x = −b/(2a) = 4/2 = 2.'], TOPIC_QUESTION('algebra-9-quadratics-q4', 'single', "При каком условии ветви параболы y = ax² направлены вниз?", ["b = 0","a > 0","a < 0"], 2, "Отрицательный коэффициент a отражает ветви параболы вниз."), TOPIC_QUESTION('algebra-9-quadratics-q5', 'single', "Через какую точку проходит график функции y = x² − 2?", ["(0; 2)","(0; −2)","(−2; 0)"], 1, "При x = 0 значение y равно −2.")] },
  { id: 'physics-9-ohm', grade: 9, subjectId: 'physics', section: 'Электрические явления', title: 'Закон Ома', description: 'Связь силы тока, напряжения и сопротивления.', difficulty: 'medium', theoryHtml: '<h3>Закон Ома для участка цепи</h3><p>Сила тока в участке цепи прямо пропорциональна напряжению и обратно пропорциональна сопротивлению.</p><div class="formula-card">I = U / R</div><div class="theory-callout"><strong>Единицы:</strong> ток — амперы, напряжение — вольты, сопротивление — омы.</div>', questions: [['Как вычислить силу тока по напряжению и сопротивлению?', ['I = U/R', 'I = U·R', 'I = R/U'], 0, 'Закон Ома: сила тока равна напряжению, делённому на сопротивление.'], ['Напряжение 12 В, сопротивление 3 Ом. Чему равен ток?', ['4 А', '9 А', '36 А'], 0, 'I = 12/3 = 4 А.'], ['В каких единицах измеряют сопротивление?', ['Ом', 'Вольт', 'Ампер'], 0, 'Единица сопротивления — ом.'], TOPIC_QUESTION('physics-9-ohm-q4', 'input', "Напряжение 9 В, сопротивление 3 Ом. Чему равна сила тока (в амперах)?", null, "3", "I = U/R = 9 : 3 = 3 А."), TOPIC_QUESTION('physics-9-ohm-q5', 'single', "В каких единицах измеряют электрическое напряжение?", ["ампер","ом","вольт"], 2, "Напряжение измеряют в вольтах, силу тока — в амперах.")] },
  { id: 'chemistry-9-atoms', grade: 9, subjectId: 'chemistry', section: 'Строение атома', title: 'Состав атома', description: 'Протоны, нейтроны, электроны и заряд ядра.', difficulty: 'medium', theoryHtml: '<h3>Строение атома</h3><p>В ядре атома находятся положительно заряженные протоны и нейтральные нейтроны. Вокруг ядра движутся отрицательно заряженные электроны.</p><div class="theory-callout"><strong>Нейтральный атом:</strong> число электронов равно числу протонов.</div>', questions: [['Какие частицы входят в состав атомного ядра?', ['Протоны и нейтроны', 'Только электроны', 'Нейтроны и молекулы'], 0, 'Протоны и нейтроны находятся в ядре атома.'], ['Какой заряд у электрона?', ['Отрицательный', 'Положительный', 'Нейтральный'], 0, 'Электрон имеет отрицательный электрический заряд.'], ['Сколько электронов у нейтрального атома с 8 протонами?', ['8', '16', '0'], 0, 'В нейтральном атоме число электронов равно числу протонов.'], TOPIC_QUESTION('chemistry-9-atoms-q4', 'single', "Какой электрический заряд имеет протон?", ["отрицательный","положительный","нейтральный"], 1, "Протон заряжен положительно, электрон — отрицательно."), TOPIC_QUESTION('chemistry-9-atoms-q5', 'input', "Сколько нейтронов содержит атом с массовым числом 12 и 6 протонами?", null, "6", "Число нейтронов равно разности массового числа и числа протонов: 12 − 6 = 6.")] },
  { id: 'algebra-10-trigonometry', grade: 10, subjectId: 'algebra', section: 'Тригонометрия', title: 'Основные значения синуса и косинуса', description: 'Единичная окружность и табличные значения функций.', difficulty: 'medium', theoryHtml: '<h3>Тригонометрические функции</h3><p>На единичной окружности косинус угла задаёт абсциссу точки, а синус — её ординату.</p><div class="formula-card">sin 0 = 0 · cos 0 = 1 · sin(π/2) = 1</div><div class="theory-callout"><strong>Важно:</strong> углу π радиан соответствует 180°.</div>', questions: [['Чему равен cos 0?', ['1', '0', '−1'], 0, 'Точка единичной окружности при угле 0 имеет координаты (1; 0).'], ['Чему равен sin(π/2)?', ['1', '0', '−1'], 0, 'При π/2 ордината точки единичной окружности равна 1.'], ['Сколько градусов составляют π радиан?', ['180°', '90°', '360°'], 0, 'Половина полного оборота — π радиан, то есть 180°.'], TOPIC_QUESTION('algebra-10-trigonometry-q4', 'single', "Чему равен sin 0?", ["1","0","−1"], 1, "Синус нулевого угла равен нулю."), TOPIC_QUESTION('algebra-10-trigonometry-q5', 'single', "Чему равен tg(π/4)?", ["0","2","1"], 2, "sin(π/4) = cos(π/4), поэтому их отношение равно 1.")] },
  { id: 'physics-10-kinematics', grade: 10, subjectId: 'physics', section: 'Кинематика', title: 'Равноускоренное движение', description: 'Ускорение, скорость и путь при постоянном ускорении.', difficulty: 'medium', theoryHtml: '<h3>Ускорение</h3><p>Ускорение показывает, как быстро меняется скорость тела. При равноускоренном движении ускорение постоянно.</p><div class="formula-card">a = (v − v₀) / t</div><div class="theory-callout"><strong>Единица СИ:</strong> метр в секунду за секунду (м/с²).</div>', questions: [['Что характеризует ускорение?', ['Изменение скорости за единицу времени', 'Пройденный путь', 'Массу тела'], 0, 'Ускорение равно изменению скорости, делённому на время.'], ['Скорость выросла с 2 до 10 м/с за 4 с. Найди ускорение.', ['2 м/с²', '3 м/с²', '8 м/с²'], 0, 'a = (10 − 2)/4 = 2 м/с².'], ['Какова единица ускорения в СИ?', ['м/с²', 'м/с', 'Н'], 0, 'Ускорение измеряют в метрах на секунду в квадрате.'], TOPIC_QUESTION('physics-10-kinematics-q4', 'input', "Начальная скорость равна 0, ускорение 2 м/с². Чему равна скорость через 5 с (в м/с)?", null, "10", "v = v₀ + at = 0 + 2 · 5 = 10 м/с."), TOPIC_QUESTION('physics-10-kinematics-q5', 'single', "Какая формула описывает скорость при равноускоренном движении?", ["v = s · t","v = v₀ + at","v = at²"], 1, "Скорость меняется линейно со временем: v = v₀ + at.")] },
  { id: 'chemistry-10-periodic', grade: 10, subjectId: 'chemistry', section: 'Периодический закон', title: 'Периодическая таблица', description: 'Порядковый номер элемента и строение атома.', difficulty: 'medium', theoryHtml: '<h3>Порядковый номер</h3><p>Порядковый номер элемента равен заряду ядра атома и числу протонов. В нейтральном атоме он также равен числу электронов.</p><div class="theory-callout"><strong>Пример:</strong> у кислорода порядковый номер 8, значит, в его ядре 8 протонов.</div>', questions: [['Что показывает порядковый номер элемента?', ['Заряд ядра и число протонов', 'Число нейтронов всегда', 'Число молекул'], 0, 'Порядковый номер равен числу протонов в ядре.'], ['Сколько протонов у атома углерода с номером 6?', ['6', '12', '3'], 0, 'Заряд ядра углерода равен +6, в нём шесть протонов.'], ['Сколько электронов у нейтрального атома натрия с номером 11?', ['11', '22', '10'], 0, 'В нейтральном атоме число электронов равно числу протонов.'], TOPIC_QUESTION('chemistry-10-periodic-q4', 'single', "Сколько элементов содержит первый период периодической таблицы?", ["8","2","18"], 1, "Первый период короткий и включает водород и гелий — два элемента."), TOPIC_QUESTION('chemistry-10-periodic-q5', 'single', "Что общего у элементов одной главной группы?", ["одинаковое число протонов","одинаковое число электронов на внешнем уровне","одинаковая атомная масса"], 1, "Номер главной группы равен числу электронов на внешнем энергетическом уровне.")] },
  { id: 'history-10-revolution', grade: 10, subjectId: 'history', section: 'Россия в начале XX века', title: 'Революция 1905–1907 годов', description: 'Причины революции, события и первые политические изменения.', difficulty: 'medium', theoryHtml: '<h3>Первая российская революция</h3><p>Революция 1905–1907 годов была связана с социальными противоречиями, аграрным вопросом и политическим устройством страны. После событий 1905 года появилась Государственная дума.</p><div class="theory-callout"><strong>Итог:</strong> Манифест 17 октября 1905 года провозгласил гражданские свободы и создание законодательной Думы.</div>', questions: [['В каком году был издан Манифест 17 октября?', ['1905', '1917', '1901'], 0, 'Манифест был издан 17 октября 1905 года.'], ['Какое учреждение появилось в результате политических преобразований?', ['Государственная дума', 'Земский собор', 'Сенат Петра I'], 0, 'В стране была создана Государственная дума.'], ['Какой вопрос был одной из причин революции?', ['Аграрный', 'Освоение космоса', 'Создание ООН'], 0, 'Земельный вопрос оставался важным социальным противоречием.'], TOPIC_QUESTION('history-10-revolution-q4', 'single', "Когда произошло Кровавое воскресенье — начало революции 1905 года?", ["в октябре 1905 года","в январе 1905 года","в декабре 1905 года"], 1, "Расстрел шествия рабочих произошёл 9 января 1905 года."), TOPIC_QUESTION('history-10-revolution-q5', 'single', "Какие свободы провозгласил Манифест 17 октября 1905 года?", ["свободу слова, собраний и союзов","отмену крепостного права","национализацию помещичьих земель"], 0, "Манифест даровал гражданские свободы и учредил Государственную думу.")] },
  { id: 'russian-10-parts', grade: 10, subjectId: 'russian', section: 'Синтаксис', title: 'Однородные члены предложения', description: 'Однородные члены и пунктуация при перечислении.', difficulty: 'easy', theoryHtml: '<h3>Однородные члены</h3><p>Однородные члены отвечают на один вопрос и относятся к одному слову. Между ними без одиночного союза обычно ставится запятая.</p><div class="theory-callout"><strong>Пример:</strong> На столе лежали книги, тетради и карандаши.</div>', questions: [['Какие слова являются однородными в предложении «Мы купили яблоки, груши и сливы»?', ['Яблоки, груши и сливы', 'Мы и купили', 'Купили и на'], 0, 'Это однородные дополнения, отвечающие на вопрос «что?».'], ['Какой знак обычно ставится между однородными членами без союза?', ['Запятая', 'Точка с запятой всегда', 'Вопросительный знак'], 0, 'При перечислении без союза однородные члены разделяются запятыми.'], ['Какой союз соединяет однородные члены в примере?', ['и', 'потому что', 'если'], 0, 'В примере «яблоки, груши и сливы» однородные члены соединены союзом «и».'], TOPIC_QUESTION('russian-10-parts-q4', 'single', "Нужна ли запятая между однородными членами, соединёнными одиночным союзом И?", ["да, всегда","нет","только перед существительными"], 1, "Одиночный союз И соединяет однородные члены без запятой."), TOPIC_QUESTION('russian-10-parts-q5', 'single', "Могут ли сказуемые быть однородными?", ["да","нет","только в вопросительных предложениях"], 0, "Однородными могут быть любые члены, отвечающие на один вопрос.")] },
  { id: 'algebra-11-probability', grade: 11, subjectId: 'algebra', section: 'Теория вероятностей', title: 'Классическая вероятность', description: 'Вероятность равновозможного случайного события.', difficulty: 'medium', theoryHtml: '<h3>Вероятность события</h3><p>Если все исходы равновозможны, вероятность события равна отношению числа благоприятных исходов к числу всех исходов.</p><div class="formula-card">P(A) = m / n</div><div class="theory-callout"><strong>Пример:</strong> вероятность выпадения чётного числа на кубике равна 3/6 = 1/2.</div>', questions: [['Как найти классическую вероятность события?', ['Благоприятные исходы разделить на все исходы', 'Все исходы умножить на 2', 'Сложить исходы'], 0, 'P(A) = m/n, где m — число благоприятных, n — число всех исходов.'], ['Какова вероятность выпадения орла при броске правильной монеты?', ['1/2', '1/4', '1'], 0, 'У монеты два равновозможных исхода, один из них — орёл.'], ['На кубике выпадают числа от 1 до 6. Какова вероятность числа больше 4?', ['1/3', '1/2', '2/3'], 0, 'Благоприятны 5 и 6: вероятность 2/6 = 1/3.'], TOPIC_QUESTION('algebra-11-probability-q4', 'single', "Чему равна вероятность достоверного события?", ["0","0,5","1"], 2, "Достоверное событие происходит всегда, его вероятность равна единице."), TOPIC_QUESTION('algebra-11-probability-q5', 'input', "Сколько равновозможных исходов даёт бросок двух монет?", null, "4", "Орёл или решка у каждой монеты: 2 · 2 = 4 исхода.")] },
  { id: 'physics-11-energy', grade: 11, subjectId: 'physics', section: 'Электродинамика', title: 'Мощность электрического тока', description: 'Работа тока и мощность в электрической цепи.', difficulty: 'medium', theoryHtml: '<h3>Мощность тока</h3><p>Электрическая мощность показывает, какую работу совершает ток за единицу времени.</p><div class="formula-card">P = U · I</div><div class="theory-callout"><strong>Единица мощности:</strong> ватт (Вт).</div>', questions: [['Как вычислить мощность электрического тока?', ['P = U·I', 'P = U/I', 'P = I/U'], 0, 'Мощность равна произведению напряжения на силу тока.'], ['При напряжении 12 В и токе 2 А найди мощность.', ['24 Вт', '6 Вт', '14 Вт'], 0, 'P = 12·2 = 24 Вт.'], ['В каких единицах измеряется мощность?', ['Ватт', 'Ампер', 'Ом'], 0, 'Единица мощности в СИ — ватт.'], TOPIC_QUESTION('physics-11-energy-q4', 'input', "Напряжение 220 В, сила тока 1 А. Чему равна мощность (в ваттах)?", null, "220", "P = U · I = 220 · 1 = 220 Вт."), TOPIC_QUESTION('physics-11-energy-q5', 'single', "В каких единицах измеряют работу электрического тока?", ["ватт","джоуль","ампер"], 1, "Работу измеряют в джоулях, мощность — в ваттах.")] },
  { id: 'russian-11-complex', grade: 11, subjectId: 'russian', section: 'Сложное предложение', title: 'Виды сложных предложений', description: 'Различие между сочинительной, подчинительной и бессоюзной связью.', difficulty: 'medium', theoryHtml: '<h3>Связь частей сложного предложения</h3><p>В сложносочинённом предложении части равноправны; в сложноподчинённом одна часть зависит от другой; в бессоюзном связь выражается интонацией и знаками препинания.</p><div class="theory-callout"><strong>Алгоритм:</strong> найди грамматические основы, затем определи союз или отсутствие союза.</div>', questions: [['Как связаны части сложноподчинённого предложения?', ['Одна часть зависит от другой', 'Они всегда равноправны', 'Между ними нет смысловой связи'], 0, 'В СПП есть главная и зависимая придаточная части.'], ['Как обычно соединены части сложносочинённого предложения?', ['Сочинительным союзом', 'Только подчинительным союзом', 'Только двоеточием'], 0, 'Части ССП равноправны и часто соединены сочинительными союзами.'], ['Чем соединяются части бессоюзного сложного предложения?', ['Интонацией и знаками препинания', 'Только союзом «что»', 'Предлогом'], 0, 'В БСП союзов между частями нет, связь передают интонация и пунктуация.'], TOPIC_QUESTION('russian-11-complex-q4', 'single', "Какое предложение является бессоюзным сложным?", ["Ветер стих, и стало тихо.","Ветер стих — стало тихо.","Ветер стих, поэтому стало тихо."], 1, "Части связаны только интонацией, союз отсутствует."), TOPIC_QUESTION('russian-11-complex-q5', 'single', "Подчинительные союзы (что, потому что, чтобы) связывают части…", ["сложносочинённого предложения","бессоюзного предложения","сложноподчинённого предложения"], 2, "Подчинительные союзы соединяют главное и придаточное предложения.")] }
].forEach(addCurriculumTopic);

